def _load_settings(path: Path) -> tuple[str | None, dict[str, Any]]:
    if not path.exists():
        return None, {}
    text = path.read_text("utf-8")
    try:
        settings = json.loads(text) if text.strip() else {}
    except json.JSONDecodeError:
        raise HookInstallError(f"{path} is not valid JSON") from None
    if not isinstance(settings, dict):
        raise HookInstallError(f"{path} must hold a JSON object")
    return text, settings

def load_config(path: Path | None = None) -> AppConfig:
    """Load configuration from ``path`` or the canonical user configuration path.

    An absent canonical configuration file means the documented defaults are used. An
    explicitly supplied path must exist.
    """
    config_path = (
        path.expanduser().resolve(strict=False) if path is not None else DEFAULT_CONFIG_PATH
    )
    if not config_path.exists():
        if path is not None:
            raise ConfigurationError(f"configuration file does not exist: {config_path}")
        return AppConfig()
    if not config_path.is_file():
        raise ConfigurationError(f"configuration path is not a file: {config_path}")
    try:
        with config_path.open("rb") as handle:
            document = tomllib.load(handle)
    except tomllib.TOMLDecodeError as exc:
        raise ConfigurationError(f"invalid TOML in {config_path}: {exc}") from exc
    except OSError as exc:
        raise ConfigurationError(f"configuration file cannot be read: {config_path}") from exc
    return parse_config(document)

const byDay = (rows: Row[], cells: (row: Row) => Row): Row[] => {
  const days = new Map<string, Row>();
  for (const row of rows) {
    const day = String(row.day);
    days.set(day, { ...(days.get(day) ?? { day }), ...cells(row) });
  }
  return [...days.values()].sort((a, b) =>
    String(a.day).localeCompare(String(b.day)),
  );
};

function wideByDay(
  rows: Row[],
  pick: (row: Row) => string | null,
  value: (row: Row) => number | null,
): Row[] {
  const days = new Map<string, Row>();
  for (const row of rows) {
    const series = pick(row);
    if (series === null) continue;
    const day = String(row.day);
    days.set(day, { ...days.get(day), day, [series]: value(row) });
  }
  return [...days.values()];
}

