def entries(lines: list[str]) -> list[dict[str, Any]]:
    """Group bullet lines (with any indented continuation lines) into typed entries."""
    out: list[dict[str, Any]] = []
    for ln in lines:
        m = BULLET.match(ln)
        if m:
            out.append({"type": m.group(1).lower(), "breaking": bool(m.group(3)), "text": ln})
        elif ln.strip() and out and ln.startswith(("  ", "\t")):
            out[-1]["text"] += "\n" + ln
            if "BREAKING CHANGE:" in ln:
                out[-1]["breaking"] = True
        elif ln.strip():
            raise SystemExit(f"CHANGELOG Unreleased line isn't '- type: summary': {ln!r}")
    for e in out:
        if e["type"] not in KNOWN:
            raise SystemExit(f"Unknown change type '{e['type']}' (use one of {', '.join(sorted(KNOWN))}).")
    return out

