def _read_scenario(p: Path) -> dict[str, Any]:
    """One allocation file as a scenario, or a ValueError that names the file: empty, unparseable, not a mapping, or an
    id that is not its file name (so a copied file that kept another scenario's id cannot silently replace it)."""
    name = f"config/allocations/{p.name}"
    try:
        s = load_yaml(p)
    except yaml.YAMLError as e:
        raise ValueError(f"{name} isn't valid YAML ({type(e).__name__}); fix it or restore it from git") from e
    if not s or not isinstance(s, dict):
        raise ValueError(f"{name} is empty or not a mapping; fix it or restore it from git")
    if s.get("id") != p.stem:
        raise ValueError(f"{name} has id {s.get('id')!r}; a scenario's id must be its file name ({p.stem!r})")
    return s

def load_scenarios() -> dict[str, dict[str, Any]]:
    """Every scenario in config/allocations, keyed by id. An invalid file raises an error that names it."""
    return {p.stem: _read_scenario(p) for p in sorted((CONFIG_DIR / "allocations").glob("*.yaml"))}

