def table(columns: Sequence[str], rows: Sequence[Sequence[Cell]], *, numeric: Sequence[str] = (),
          notes: dict[str, str] | None = None, where: DeltaGenerator | None = None) -> None:
    """A read-only table in the ledger style: hairline rows, numbers right-aligned and tabular. Use st.dataframe
    for large, sortable data; this for short tables whose cells carry chips or two-line text. Keep headers short so
    the values set the column widths: `notes` maps a short header to its full meaning, shown in an ⓘ popover (a
    header that is a glossary term uses [[Term|short]] instead)."""
    notes = notes or {}
    num_cols = {i for i, c in enumerate(columns) if c in set(numeric)}
    head = "".join(f"<th class='{'fp-num' if i in num_cols else ''}'>"
                   f"{_source_html(notes[c], c) if c in notes else rich(c, auto=False)}</th>"
                   for i, c in enumerate(columns))
    body = "".join("<tr>" + "".join(f"<td class='{'fp-num' if i in num_cols else ''}'>{_cell(v, i in num_cols)}</td>"
                                    for i, v in enumerate(r)) + "</tr>" for r in rows)
    (where or st).markdown(f"<table class='fp-slices'><tr>{head}</tr>{body}</table>", unsafe_allow_html=True)

def show(conn: sqlite3.Connection) -> dict[str, Any] | None:
    """The latest check-in with what changed since the one before it on the same plan (`fp checkin show`).

    `previous` is that earlier check-in (None for the first on a plan) and `changes` holds, per figure both have,
    the movement and the date it is measured from. A figure missing at either end has no entry."""
    last = latest(conn)
    if last is None:
        return None
    prev = previous(conn, date.fromisoformat(last["as_of"]), last["scenario_id"])
    changes: dict[str, dict[str, Any]] = {}
    for key, value in last["figures"].items():
        moved = change(float(value), prev, key) if value is not None else None
        if moved is not None:
            changes[key] = {"change": moved[0], "since": prev["as_of"] if prev else None}
    return {**last, "previous": prev, "changes": changes}

