def uk_tax_year(on: date) -> int:
    """The year a UK tax year starts in: it runs from 6 April."""
    return on.year if (on.month, on.day) >= (4, 6) else on.year - 1

def terms_in(text: str) -> str:
    """Plain text with the first mention on this page of each glossary term marked [[Term|as written]], for blocks
    that don't mark terms themselves (table() and link_table() cells). Text inside markers and `code` is left alone."""
    done = _marked()
    for n in _BY_LENGTH:
        if n in done:
            continue
        pat = _RAW_PATTERNS.setdefault(n, re.compile(r"(?<![\w-])" + _spaced(n) + r"(?:e?s)?(?![\w-])", re.I))
        parts = re.split(r"(\[\[.*?\]\]|`[^`]*`)", text)
        for i, part in enumerate(parts):
            if part.startswith(("[[", "`")):
                continue
            m = pat.search(part)
            if m:
                parts[i] = f"{part[:m.start()]}[[{n}|{m.group(0)}]]{part[m.end():]}"
                done.add(n)
                break
        text = "".join(parts)
    return text

pub(crate) fn get<T: serde::de::DeserializeOwned>(
    client: &reqwest::blocking::Client,
    connection: &Connection,
    path: &str,
) -> Result<T, String> {
    let response = client
        .get(format!(
            "{}{path}",
            connection.inspector_url.trim_end_matches('/')
        ))
        .bearer_auth(&connection.token)
        .send()
        .map_err(|_| {
            "Relay unavailable. Start jev-bridge or check its connection file.".to_string()
        })?;
    if !response.status().is_success() {
        return Err(format!(
            "Inspector returned HTTP {}. The relay may have restarted or this exchange was evicted.",
            response.status().as_u16()
        ));
    }
    let mut bytes = vec![];
    response
        .take(2 * 1024 * 1024 + 1)
        .read_to_end(&mut bytes)
        .map_err(|_| "Inspector response was interrupted.")?;
    if bytes.len() > 2 * 1024 * 1024 {
        return Err("Inspector response exceeds the local display budget.".into());
    }
    serde_json::from_slice(&bytes).map_err(|_| "Inspector returned an unsupported response.".into())
