func run(ctx context.Context, args []string) int {
	if len(args) == 0 {
		names := make([]string, len(commands))
		for index, command := range commands {
			names[index] = command.name
		}
		fmt.Fprintf(os.Stderr, "usage: scout <%s> [flags]\n", strings.Join(names, "|"))
