def _is_evaluation_schema_current(checkpoint_dir: Path) -> bool:
    """Check if evaluation.json has current schema version and evaluation/ dir is valid."""
    eval_path = checkpoint_dir / "evaluation.json"
    eval_dir = checkpoint_dir / "evaluation"

    if not eval_path.exists():
        return False

    try:
        with eval_path.open() as f:
            data = json.load(f)

        # Check schema version
        schema_version = data.get("schema_version")
        if schema_version is None or schema_version < EVALUATION_SCHEMA_VERSION:
            return False

        # Check required fields exist
        if not all(field in data for field in REQUIRED_EVAL_FIELDS):
            return False

        # Check evaluation/ directory has required files
        if not eval_dir.exists() or not eval_dir.is_dir():
            return False

        return all((eval_dir / f).exists() for f in REQUIRED_EVAL_DIR_FILES)
    except (OSError, json.JSONDecodeError):
        return False

def _discover_run_dirs(runs_dir: Path) -> list[Path]:
    if (runs_dir / CHECKPOINT_RESULTS_FILENAME).exists():
        return [runs_dir]

    run_dirs: set[Path] = set()
    for results_file in runs_dir.rglob(CHECKPOINT_RESULTS_FILENAME):
        run_dirs.add(results_file.parent)
    return sorted(run_dirs)

def discover_run_directories(collection_dir: Path) -> list[Path]:
    """Discover run directories by finding config.yaml files with 'agent' field.

    A run directory is identified by containing a config.yaml file that has
    an 'agent' key at the top level.

    Args:
        collection_dir: Path to search for run directories.

    Returns:
        Sorted list of valid run directory paths.
    """
    run_dirs: list[Path] = []

    for config_file in collection_dir.rglob(common.CONFIG_FILENAME):
        # Skip snapshot directories (problem test data)
        if "snapshot" in config_file.parts:
            continue

        try:
            with config_file.open() as f:
                config_data = yaml.safe_load(f)

            if isinstance(config_data, dict) and "agent" in config_data:
                run_dirs.append(config_file.parent)
        except (yaml.YAMLError, OSError):
            continue

    return sorted(run_dirs)

