def plan_buys(target: dict[str, float], current: dict[str, float], amount: float, *,
              hold_to_target: bool = False) -> list[dict[str, Any]]:
    """Split amount across sleeves so that post-buy weights move as close to target as possible."""
    if not math.isfinite(amount) or amount < 0:
        raise ValueError("amount must be a number of pounds, zero or more (this never sells)")
    target = {k: v for k, v in target.items() if v > 0}
    total_after = sum(current.values()) + amount
    gaps = {k: max(0.0, target[k] * total_after - current.get(k, 0.0)) for k in target}
    gap_sum = sum(gaps.values())
    if hold_to_target:
        buys = {k: gaps[k] * min(1.0, amount / gap_sum) if gap_sum > 1e-9 else 0.0 for k in target}
    elif gap_sum <= 1e-9:
        buys = {k: amount * w for k, w in target.items()}
    elif gap_sum <= amount:
        rest = amount - gap_sum
        buys = {k: gaps[k] + rest * target[k] for k in target}
    else:
        buys = {k: amount * gaps[k] / gap_sum for k in target}
    return [{"sleeve": k, "target": target[k], "current": current.get(k, 0.0), "buy": round(buys[k], 2)}
            for k in sorted(target, key=lambda s: -buys[s])]

