def cap_crypto(weights: dict[str, float], crypto: set[str], cap: float = CRYPTO_CAP) -> dict[str, float]:
    """Scale the crypto sleeves down together so they hold at most cap; the cut goes to global_core."""
    held = sum(w for s, w in weights.items() if s in crypto)
    if held <= cap + 1e-12:
        return dict(weights)
    scale = cap / held
    out = {s: (w * scale if s in crypto else w) for s, w in weights.items()}
    out["global_core"] = out.get("global_core", 0.0) + held - cap
    return out

