class LivenessMonitor:
    """Samples counters on a timer and makes the idle decision for one agent phase."""

    def __init__(self, config: LivenessConfig) -> None:
        self.config = config
        self.samples: deque[tuple[float, int, int]] = deque(maxlen=config.max_samples)
        self.last_output = time.monotonic()
        self.decided = False

    def on_output(self) -> None:
        self.last_output = time.monotonic()

    def add_sample(self, cpu_ticks: int, net_bytes: int) -> None:
        self.samples.append((time.monotonic(), cpu_ticks, net_bytes))

    def idle(self) -> bool:
        now = time.monotonic()
        if now - self.last_output < self.config.idle_s or len(self.samples) < 2:
            return False
        window = [s for s in self.samples if now - s[0] <= self.config.idle_s]
        if len(window) < 2:
            return False
        span = window[-1][0] - window[0][0] or 1.0
        cpu_rate = (window[-1][1] - window[0][1]) / span
        net_rate = (window[-1][2] - window[0][2]) / span
        return cpu_rate < self.config.cpu_ticks_per_s and net_rate < self.config.net_bytes_per_s

