from raidar.engine.job.detach import stop_trial
from raidar.engine.job.manifest import read_trials


class JobShell(cmd.Cmd):
    def __init__(self, job_dir: Path) -> None:
        super().__init__()
        self.job_dir = job_dir
        self.prompt = f"({job_dir.name}) "

    def do_ls(self, arg: str) -> None:
        """ls [state]: list trials, optionally only those in one state."""
        for entry in read_trials(self.job_dir):
            if arg and entry.state != arg:
                continue
            print(f"{entry.trial:40} {entry.state:10} {entry.container or '-':20} {entry.started or '-'}")

    def do_stop(self, arg: str) -> None:
        """stop <trial>: remove its container and mark it stopped."""
        if not arg:
            print("usage: stop <trial>")
            return
        if input(f"stop {arg}? [y/N] ").strip().lower() == "y":
            stop_trial(self.job_dir, arg)

    def do_stopall(self, arg: str) -> None:
        """stopall: stop every running trial."""
        running = [e.trial for e in read_trials(self.job_dir) if e.state == "running"]
        if running and input(f"stop {len(running)} trials? [y/N] ").strip().lower() == "y":
            for trial in running:
                stop_trial(self.job_dir, trial)

    def do_quit(self, arg: str) -> bool:
        """quit"""
        return True


