import sys

from raidar.design.problem.errata import STATUSES, add_erratum, set_status
from raidar.design.problem.store import open_store

HELP = "[n]ext  [p]rev  [s]tatus <" + "|".join(STATUSES) + ">  [e]rratum <text>  [q]uit"


def main() -> None:
    store = open_store()
    records = store.list()
    if len(sys.argv) > 1:
        records = [r for r in records if r.status == sys.argv[1]]
    i = 0
    while records:
        record = records[i]
        print(f"\n[{i + 1}/{len(records)}] {record.name}  status={record.status}  checkpoints={record.checkpoints}")
        for line in record.errata:
            print(f"  erratum: {line}")
        command, _, rest = input(f"{HELP}\n> ").strip().partition(" ")
        if command == "q":
            break
        if command == "n":
            i = min(i + 1, len(records) - 1)
        elif command == "p":
            i = max(i - 1, 0)
        elif command == "s":
            store.save(set_status(record, rest))
        elif command == "e" and rest:
            store.save(add_erratum(record, rest))


