"""The raidar perf check report over real runs: budgets, warnings and contention.

Every phase is reported against its accepted budget and breaches become warnings;
--strict turns breaches back into a failure.
"""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass

from raidar.engine.perf.budgets import JobSamples, p95

BUDGETS = {"provision": 45.0, "agent_start": 20.0, "grade": 90.0}


@dataclass(frozen=True)
class PhaseCheck:
    phase: str
    samples: int
    p95: float | None
    budget: float

    @property
    def breached(self) -> bool:
        return self.p95 is not None and self.p95 > self.budget


@dataclass(frozen=True)
class PerfReport:
    checks: list[PhaseCheck]

    @property
    def breaches(self) -> list[PhaseCheck]:
        return [c for c in self.checks if c.breached]

    def lines(self) -> list[str]:
        out = []
        for c in self.checks:
            shown = f"{c.p95:.2f}" if c.p95 is not None else "-"
            verdict = "BREACH" if c.breached else "ok"
            out.append(f"  {verdict:8} {c.phase:20} n={c.samples:<4} p95={shown:>7} budget={c.budget:g}s")
        return out


def build_report(samples: Sequence[JobSamples]) -> PerfReport:
    checks = []
    for phase, budget in BUDGETS.items():
        values = [v for s in samples for v in s.phases.get(phase, [])]
        checks.append(PhaseCheck(phase, len(values), p95(values), budget))
    return PerfReport(checks)

