"""Run portable parse/refusal/digest vectors: python -m raidar_contract.conformance.check."""

from __future__ import annotations

import json
import sys
from pathlib import Path
from typing import Any

import yaml
from pydantic import ValidationError
from raidar_contract.canonical import digest_json
from raidar_contract.package.manifest import parse_manifest

VECTORS = Path(__file__).with_name("vectors.json")


def _manifest(case: dict[str, Any]) -> dict[str, Any]:
    value = parse_manifest(yaml.safe_dump(case["input"])).model_dump(mode="json")
    return {"value": value, "digest": digest_json(value)}


def run(vectors: list[dict[str, Any]]) -> list[str]:
    failures = []
    for case in vectors:
        try:
            got: dict[str, Any] = _manifest(case)
        except ValidationError:
            got = {"refused": True}
        if got != case["expected"]:
            failures.append(f"{case['id']}: expected {case['expected']}, got {got}")
    return failures


def main() -> None:
    failures = run(json.loads(VECTORS.read_text()))
    for failure in failures:
        print(failure, file=sys.stderr)
    print(f"{len(failures)} failing vectors")
    sys.exit(1 if failures else 0)


if __name__ == "__main__":
    main()

"""Shadow audit report for the rubric question set: coverage and input sufficiency.

- request: one Jev question batch for one symbol and one required input.
- asked: requests the policy wanted answered this checkpoint, i.e. not carried forward.
- input sufficiency: sufficient asked requests / asked requests.
- symbol coverage: symbols whose every request is settled / symbols.
"""

from __future__ import annotations

from collections.abc import Sequence
from typing import Any

from raidar.scoring.judge.rubric import Judgement, JudgementStatus


def _ratio(numerator: int, denominator: int) -> dict[str, Any]:
    value = round(numerator / denominator, 4) if denominator else None
    return {"numerator": numerator, "denominator": denominator, "value": value}


def _asked(judgement: Judgement) -> bool:
    return judgement.status not in {JudgementStatus.CARRIED, JudgementStatus.SKIPPED}


def audit_report(judgements: Sequence[Judgement]) -> dict[str, Any]:
    asked = [j for j in judgements if _asked(j)]
    symbols = {j.symbol for j in judgements}
    settled = {s for s in symbols if all(j.status != JudgementStatus.MISSING for j in judgements if j.symbol == s)}
    return {
        "input_sufficiency": _ratio(sum(j.sufficient for j in asked), len(asked)),
        "symbol_coverage": _ratio(len(settled), len(symbols)),
        "asked": len(asked),
        "carried": sum(j.status == JudgementStatus.CARRIED for j in judgements),
    }

package eval

import (
	"fmt"
	"sort"
	"strings"
)

// EvaluationStatus states whether this comparison had enough evidence to assess
// the requested target input.
type EvaluationStatus string

const (
	EvaluationComplete         EvaluationStatus = "complete"
	EvaluationMissingCorpus    EvaluationStatus = "missing_corpus"
	EvaluationUnsupportedInput EvaluationStatus = "unsupported_input"
	EvaluationIncomplete       EvaluationStatus = "incomplete"
)

// Outcome is one corpus case compared with Scout's observation.
type Outcome struct {
	CaseID   string
	Expected bool
	Observed bool
}

// Summary counts agreement over a set of outcomes.
type Summary struct {
	Status         EvaluationStatus
	TruePositives  int
	FalsePositives int
	FalseNegatives int
	TrueNegatives  int
}

// Summarize counts agreement; an empty corpus is missing, never complete.
func Summarize(outcomes []Outcome) Summary {
	if len(outcomes) == 0 {
		return Summary{Status: EvaluationMissingCorpus}
	}
	s := Summary{Status: EvaluationComplete}
	for _, o := range outcomes {
		switch {
		case o.Expected && o.Observed:
			s.TruePositives++
		case !o.Expected && o.Observed:
			s.FalsePositives++
		case o.Expected && !o.Observed:
			s.FalseNegatives++
		default:
			s.TrueNegatives++
		}
	}
	return s
}

// Lines renders the summary as aligned text lines, misses first.
func (s Summary) Lines(outcomes []Outcome) []string {
	sort.Slice(outcomes, func(i, j int) bool { return outcomes[i].Expected != outcomes[i].Observed && outcomes[j].Expected == outcomes[j].Observed })
	lines := []string{fmt.Sprintf("status=%s tp=%d fp=%d fn=%d tn=%d", s.Status, s.TruePositives, s.FalsePositives, s.FalseNegatives, s.TrueNegatives)}

